type Localized={ar:string;en:string;fr:string};
type Variant={name:Localized;priceDelta:string;enabled:boolean};
type Option={name:Localized;priceDelta:string;stockQuantity:string;enabled:boolean};
type Group={title:Localized;selectionType:'single'|'multiple';isRequired:boolean;minSelect:string;maxSelect:string;maxQty:string;enabled:boolean;options:Option[]};
type Editor={id:string;categoryId:string;name:Localized;description:Localized;price:string;discountPrice:string;taxRate:string;taxIncluded:boolean;stockQuantity:string;trackInventory:boolean;dietaryType:'unspecified'|'vegetarian'|'non_vegetarian';sortOrder:string;imageUrl:string;imageUrls:string[];calories:string;enabled:boolean;variants:Variant[];addonGroups:Group[]};
type ApiOption={id:string;name_ar:string;name_en:string;name_fr:string;price_delta:number|string;stock_quantity:number|string;enabled:number|string};
type ApiVariant=ApiOption;
type ApiGroup={title_ar:string;title_en:string;title_fr:string;selection_type:'single'|'multiple';is_required:number|string;min_select:number|string;max_select:number|string;max_qty:number|string;enabled:number|string;options:ApiOption[]};
type ApiCategory={id:string;name_ar:string;name_en:string;name_fr:string;image_url:string|null;sort_order:number|string;enabled:number|string};
type ApiItem={id:string;category_id:string;name_ar:string;name_en:string;name_fr:string;description_ar:string|null;description_en:string|null;description_fr:string|null;price:string|number;discount_price:string|number|null;tax_rate:string|number;tax_included:number|string;stock_quantity:number|string;track_inventory:number|string;dietary_type:'unspecified'|'vegetarian'|'non_vegetarian';sort_order:number|string;image_url:string|null;image_urls?:string[];calories:number|null;enabled:number|string;variants:ApiVariant[];addon_groups:ApiGroup[]};
type MenuData={categories:ApiCategory[];items:ApiItem[];addonLibrary:ApiOption[]};
const local=(ar='',en='',fr=''):Localized=>({ar,en,fr});
const emptyEditor=(categoryId='',sortOrder=0):Editor=>({id:'',categoryId,name:local(),description:local(),price:'',discountPrice:'',taxRate:'0',taxIncluded:true,stockQuantity:'0',trackInventory:false,dietaryType:'unspecified',sortOrder:String(sortOrder),imageUrl:idx('image_url')>=0?(row[idx('image_url')]||'').trim():'',imageUrls:idx('image_url')>=0&&(row[idx('image_url')]||'').trim()?[(row[idx('image_url')]||'').trim()]:[],calories:'',enabled:true,variants:[],addonGroups:[]});
const emptyOption=():Option=>({name:local(),priceDelta:'0',stockQuantity:'0',enabled:true});
const emptyGroup=():Group=>({title:local(),selectionType:'multiple',isRequired:false,minSelect:'0',maxSelect:'0',maxQty:'1',enabled:true,options:[emptyOption()]});
const hasEditorContent=(v:Editor)=>Boolean(v.name.ar||v.name.en||v.name.fr||v.description.ar||v.description.en||v.description.fr||v.price||v.discountPrice||v.imageUrl||v.calories||v.trackInventory||v.stockQuantity!=='0'||!v.taxIncluded||v.taxRate!=='0'||v.dietaryType!=='unspecified'||v.variants.length||v.addonGroups.length);
const title=(locale:string,ar:string,en:string,fr:string)=>locale==='ar'?ar:locale==='fr'?fr:en;
export default function RestaurantMenuManager({slug}:{slug:string}){
 const {locale}=usePreferences(),[editorStep,setEditorStep]=useState<1|2|3>(1),[data,setData]=useState<MenuData>({categories:[],items:[],addonLibrary:[]}),[busy,setBusy]=useState(false),[msg,setMsg]=useState(''),[category,setCategory]=useState(local()),[libraryForm,setLibraryForm]=useState({name:local(),price:'0',stockQuantity:'0',enabled:true}),[editingLibrary,setEditingLibrary]=useState(''),[editor,setEditor]=useState<Editor|null>(null),[uploading,setUploading]=useState(false),[addonSearch,setAddonSearch]=useState(''),[itemSearch,setItemSearch]=useState(''),[menuView,setMenuView]=useState<'items'|'addons'>('items'),[categoryFilter,setCategoryFilter]=useState(''),[showCategories,setShowCategories]=useState(false),[categoryImage,setCategoryImage]=useState(''),[categoryEditingId,setCategoryEditingId]=useState(''),[categoryUploading,setCategoryUploading]=useState(false),[sortDirection,setSortDirection]=useState<'asc'|'desc'>('asc'),[hasNewDraft,setHasNewDraft]=useState(false),addonCsvRef=useRef<HTMLInputElement>(null),editorRef=useRef<Editor|null>(null);
 const L=(ar:string,en:string,fr:string)=>title(locale,ar,en,fr);
 const draftStorageKey=`foon-menu-drafts:${slug}`;
 const readDraft=useCallback((id:string)=>{try{const drafts=JSON.parse(localStorage.getItem(draftStorageKey)||'{}') as Record<string,Editor>;return drafts[id]||null}catch{return null}},[draftStorageKey]);
 const persistDraft=useCallback((value:Editor)=>{try{const drafts=JSON.parse(localStorage.getItem(draftStorageKey)||'{}') as Record<string,Editor>;drafts[value.id||'new']=value;localStorage.setItem(draftStorageKey,JSON.stringify(drafts))}catch{}},[draftStorageKey]);
 const removeDraft=useCallback((id:string)=>{try{const drafts=JSON.parse(localStorage.getItem(draftStorageKey)||'{}') as Record<string,Editor>;delete drafts[id];localStorage.setItem(draftStorageKey,JSON.stringify(drafts))}catch{}},[draftStorageKey]);
 function openNewItem(){setEditorStep(1);setMenuView('items');const draft=readDraft('new');setHasNewDraft(Boolean(draft));setEditor(draft||emptyEditor(data.categories[0]?.id||'',data.items.length+1));setMsg(draft?L('تم استعادة مسودة الصنف.','Item draft restored.','Brouillon de l’article restauré.'): '')}
 const load=async()=>{try{const r=await fetch('/api/restaurant/menu?slug='+encodeURIComponent(slug),{cache:'no-store'}),j=await r.json() as MenuData;if(!r.ok)throw Error((j as {error?:string}).error||'MENU_LOAD_FAILED');setData(j)}catch(e){setMsg(e instanceof Error?e.message:'ERROR')}};
 useEffect(()=>{const timer=window.setTimeout(()=>{void load()},0);return()=>window.clearTimeout(timer)},[slug]);
 useEffect(()=>{editorRef.current=editor;if(editor){if(hasEditorContent(editor))persistDraft(editor);else if(!editor.id)removeDraft('new')}},[editor,persistDraft,removeDraft]);
 useEffect(()=>{const saveOnExit=()=>{if(editorRef.current)persistDraft(editorRef.current)};window.addEventListener('pagehide',saveOnExit);return()=>window.removeEventListener('pagehide',saveOnExit)},[persistDraft]);
 useEffect(()=>{const timer=window.setTimeout(()=>setHasNewDraft(Boolean(readDraft('new'))),0);return()=>window.clearTimeout(timer)},[readDraft]);
 async function send(method:string,body:Record<string,unknown>,endpoint='/api/restaurant/menu'){setBusy(true);setMsg('');try{const r=await fetch(endpoint,{method,headers:{'Content-Type':'application/json'},body:JSON.stringify({slug,...body})}),j=await r.json() as {error?:string};if(!r.ok)throw Error(j.error||'ERROR');await load();return true}catch(e){setMsg(e instanceof Error?e.message:'ERROR');return false}finally{setBusy(false)}}
 function startEdit(x:ApiItem){setEditorStep(1);const draft=readDraft(x.id);if(draft){setEditor(draft);setMsg(L('تم استعادة مسودة التعديلات.','Edit draft restored.','Brouillon de modification restauré.'));return}setEditor({id:x.id,categoryId:x.category_id,name:local(x.name_ar,x.name_en,x.name_fr),description:local(x.description_ar||'',x.description_en||'',x.description_fr||''),price:String(x.price),discountPrice:x.discount_price==null?'':String(x.discount_price),taxRate:String(x.tax_rate||0),taxIncluded:Boolean(Number(x.tax_included)),stockQuantity:String(x.stock_quantity||0),trackInventory:Boolean(Number(x.track_inventory)),dietaryType:x.dietary_type||'unspecified',sortOrder:String(x.sort_order||0),imageUrl:x.image_url||'',imageUrls:x.image_urls||[],calories:x.calories==null?'':String(x.calories),enabled:Boolean(Number(x.enabled)),variants:(x.variants||[]).map(v=>({name:local(v.name_ar,v.name_en,v.name_fr),priceDelta:String(v.price_delta),enabled:Boolean(Number(v.enabled))})),addonGroups:(x.addon_groups||[]).map(g=>({title:local(g.title_ar,g.title_en,g.title_fr),selectionType:g.selection_type,isRequired:Boolean(Number(g.is_required)),minSelect:String(g.min_select),maxSelect:String(g.max_select),maxQty:String(g.max_qty),enabled:Boolean(Number(g.enabled)),options:(g.options||[]).map(o=>({name:local(o.name_ar,o.name_en,o.name_fr),priceDelta:String(o.price_delta),stockQuantity:String(o.stock_quantity||0),enabled:Boolean(Number(o.enabled))}))}))})}
 async function uploadCategoryImage(file:File){if(!['image/jpeg','image/png','image/webp'].includes(file.type)){setMsg(L('صيغة الصورة يجب أن تكون JPG أو PNG أو WebP','Use a JPG, PNG, or WebP image','Utilisez une image JPG, PNG ou WebP'));return}setCategoryUploading(true);setMsg('');try{const form=new FormData();form.set('slug',slug);form.set('file',file);if(categoryEditingId)form.set('categoryId',categoryEditingId);const r=await fetch('/api/restaurant/menu/image',{method:'POST',body:form}),j=await r.json();if(!r.ok)throw Error(j.error||'IMAGE_UPLOAD_FAILED');setCategoryImage(j.imageUrl)}catch(e){setMsg(e instanceof Error?e.message:'IMAGE_UPLOAD_FAILED')}finally{setCategoryUploading(false)}}
 async function saveCategory(event:React.FormEvent){event.preventDefault();const ok=await send(categoryEditingId?'PATCH':'POST',{action:categoryEditingId?'update_category':'create_category',...(categoryEditingId?{id:categoryEditingId}:{}),nameAr:category.ar,nameEn:category.en,nameFr:category.fr,imageUrl:categoryImage,sortOrder:categoryEditingId?Number(data.categories.find(c=>c.id===categoryEditingId)?.sort_order||0):data.categories.length,enabled:true});if(ok){setCategory(local());setCategoryImage('');setCategoryEditingId('')}}
 async function updateCategoryOrder(index:number,direction:-1|1){const next=[...data.categories],target=index+direction;if(target<0||target>=next.length)return;[next[index],next[target]]=[next[target],next[index]];await send('PATCH',{action:'reorder_categories',ids:next.map(x=>x.id)})}
 async function updateItemOrder(item:ApiItem,direction:-1|1){const siblings=data.items.filter(x=>x.category_id===item.category_id).sort((a,b)=>Number(a.sort_order)-Number(b.sort_order)),index=siblings.findIndex(x=>x.id===item.id),target=index+direction;if(target<0||target>=siblings.length)return;[siblings[index],siblings[target]]=[siblings[target],siblings[index]];await send('PATCH',{action:'reorder_items',categoryId:item.category_id,ids:siblings.map(x=>x.id)})}
 async function upload(file:File){if(!editor)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){setMsg(L('صيغة الصورة يجب أن تكون JPG أو PNG أو WebP','Use a JPG, PNG, or WebP image','Utilisez une image JPG, PNG ou WebP'));return}setUploading(true);setMsg('');try{const form=new FormData();form.set('slug',slug);form.set('file',file);if(editor.id)form.set('itemId',editor.id);const r=await fetch('/api/restaurant/menu/image',{method:'POST',body:form}),j=await r.json();if(!r.ok)throw Error(j.error);setEditor(x=>x?{...x,imageUrl:x.imageUrl||j.imageUrl,imageUrls:Array.from(new Set([...(x.imageUrls||[]),j.imageUrl])).slice(0,8)}:x)}catch(e){setMsg(e instanceof Error?e.message:'IMAGE_UPLOAD_FAILED')}finally{setUploading(false)}}
 async function saveItem(event:React.FormEvent){event.preventDefault();if(!editor)return;const values={categoryId:editor.categoryId,nameAr:editor.name.ar,nameEn:editor.name.en,nameFr:editor.name.fr,descriptionAr:editor.description.ar,descriptionEn:editor.description.en,descriptionFr:editor.description.fr,price:Number(editor.price),discountPrice:editor.discountPrice===''?null:Number(editor.discountPrice),taxRate:Number(editor.taxRate||0),taxIncluded:editor.taxIncluded,stockQuantity:Number(editor.stockQuantity||0),trackInventory:editor.trackInventory,dietaryType:editor.dietaryType,sortOrder:Number(editor.sortOrder||0),imageUrl:editor.imageUrl,imageUrls:editor.imageUrls,calories:editor.calories?Number(editor.calories):null,enabled:editor.enabled,variants:editor.variants.filter(v=>v.name.ar.trim()).map(v=>({nameAr:v.name.ar,nameEn:v.name.en,nameFr:v.name.fr,priceDelta:Number(v.priceDelta||0),enabled:v.enabled})),addonGroups:editor.addonGroups.filter(g=>g.title.ar.trim()).map(g=>({titleAr:g.title.ar,titleEn:g.title.en,titleFr:g.title.fr,selectionType:g.selectionType,isRequired:g.isRequired,minSelect:Number(g.minSelect||0),maxSelect:Number(g.maxSelect||0),maxQty:Number(g.maxQty||1),enabled:g.enabled,options:g.options.filter(o=>o.name.ar.trim()).map(o=>({nameAr:o.name.ar,nameEn:o.name.en,nameFr:o.name.fr,priceDelta:Number(o.priceDelta||0),stockQuantity:Number(o.stockQuantity||0),enabled:o.enabled}))}))};const result=await send(editor.id?'PATCH':'POST',{action:editor.id?'update_item':'create_item',...(editor.id?{id:editor.id}:{}),...values});if(result){removeDraft(editor.id||'new');if(!editor.id)setHasNewDraft(false);setEditor(null);setMsg(L('تم حفظ الصنف وتفاصيل أسعاره','Item and pricing saved','Article et tarifs enregistrés'))}}
 function patchEditor(patch:Partial<Editor>){setEditor(x=>x?{...x,...patch}:x)}
 function saveDraftAndClose(){if(editor){persistDraft(editor);if(!editor.id)setHasNewDraft(true);setMsg(L('تم حفظ المسودة على هذا الجهاز.','Draft saved on this device.','Brouillon enregistré sur cet appareil.'))}setEditor(null)}
 function closeEditor(){if(editor){if(hasEditorContent(editor)){persistDraft(editor);if(!editor.id)setHasNewDraft(true)}else if(!editor.id)removeDraft('new')}setEditor(null)}
 function patchVariant(index:number,patch:Partial<Variant>){setEditor(x=>x?{...x,variants:x.variants.map((v,i)=>i===index?{...v,...patch}:v)}:x)}
 function patchGroup(index:number,patch:Partial<Group>){setEditor(x=>x?{...x,addonGroups:x.addonGroups.map((g,i)=>i===index?{...g,...patch}:g)}:x)}
 function patchOption(groupIndex:number,index:number,patch:Partial<Option>){setEditor(x=>x?{...x,addonGroups:x.addonGroups.map((g,gi)=>gi===groupIndex?{...g,options:g.options.map((o,i)=>i===index?{...o,...patch}:o)}:g)}:x)}
 function exportAddons(){const rows=[['name_ar','name_en','name_fr','price','stock_quantity','enabled'],...data.addonLibrary.filter(x=>`${x.name_ar} ${x.name_en} ${x.name_fr}`.toLowerCase().includes(addonSearch.toLowerCase())).map(x=>[x.name_ar,x.name_en,x.name_fr,String(x.price_delta),String(x.stock_quantity||0),String(Boolean(Number(x.enabled)))])];const csv=rows.map(row=>row.map(value=>'"'+String(value).replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='foon-menu-addons.csv';link.click();URL.revokeObjectURL(url)}
 function parseCsvLine(line:string){const values:string[]=[];let value='',quoted=false;for(let i=0;i<line.length;i++){const char=line[i];if(char==='"'&&quoted&&line[i+1]==='"'){value+='"';i++}else if(char==='"')quoted=!quoted;else if(char===','&&!quoted){values.push(value);value=''}else value+=char}values.push(value);return values}
 async function importAddons(file:File){const text=await file.text(),lines=text.replace(/^\ufeff/,'').split(/\r?\n/).filter(line=>line.trim());let imported=0;for(const line of lines.slice(1)){const [ar,en,fr,price,stock,enabled]=parseCsvLine(line);if(!ar?.trim()||!Number.isFinite(Number(price))||Number(price)<0)continue;const ok=await send('POST',{action:'create_addon_library',nameAr:ar.trim(),nameEn:en||'',nameFr:fr||'',priceDelta:Number(price),stockQuantity:Math.max(0,Number(stock)||0),enabled:enabled?.trim().toLowerCase()!=='false'});if(ok)imported++}setMsg(L(`تم استيراد ${imported} إضافة`,`Imported ${imported} add-ons`,`${imported} suppléments importés`))}
 function downloadCategoryExcelTemplate(category:ApiCategory){const xml='<?xml version="1.0"?><?mso-application progid="Excel.Sheet"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Worksheet ss:Name="Menu"><Table>'+[['name_ar','name_en','name_fr','description_ar','description_en','description_fr','price','discount_price','tax_rate','tax_included','stock_quantity','track_inventory','dietary_type','calories','image_url','enabled'],['مثال صنف','Example item','Article exemple','','','','25','','15','true','0','false','unspecified','','https://example.com/item.jpg','true']].map(row=>'<Row>'+row.map(v=>'<Cell><Data ss:Type="String">'+String(v).replaceAll('&','&amp;').replaceAll('<','&lt;')+'</Data></Cell>').join('')+'</Row>').join('')+'</Table></Worksheet></Workbook>';const url=URL.createObjectURL(new Blob([xml],{type:'application/vnd.ms-excel'})),a=document.createElement('a');a.href=url;a.download='foon-menu-'+(category.name_en||category.name_ar||'category').replace(/[^a-zA-Z0-9_-]+/g,'-')+'.xls';a.click();URL.revokeObjectURL(url)}
 async function importCategoryExcel(categoryId:string,file:File){
  setBusy(true); setMsg('');
  try{
    const xml=await file.text();
    const doc=new DOMParser().parseFromString(xml,'application/xml');
    if(doc.querySelector('parsererror')) throw new Error('INVALID_EXCEL_FILE');
    const rows=Array.from(doc.getElementsByTagNameNS('*','Row')).map(row=>Array.from(row.getElementsByTagNameNS('*','Data')).map(cell=>cell.textContent||''));
    if(rows.length<2) throw new Error('EMPTY_EXCEL_FILE');
    const headers=rows[0].map(x=>x.trim());
    const idx=(name:string)=>headers.indexOf(name);
    if(idx('name_ar')<0||idx('price')<0) throw new Error('INVALID_EXCEL_COLUMNS');
    let imported=0,rejected=0;const importRows=rows.slice(1);setExcelProgress({done:0,total:importRows.length});
    for(const [rowIndex,row] of importRows.entries()){
      const nameAr=(row[idx('name_ar')]||'').trim();
      const price=Number(row[idx('price')]);
      if(!nameAr||!Number.isFinite(price)||price<0){rejected++;continue}
      const bool=(name:string,fallback:boolean)=>idx(name)<0?fallback:!['false','0','no'].includes((row[idx(name)]||'').trim().toLowerCase());
      const num=(name:string,fallback=0)=>{const n=idx(name)<0?fallback:Number(row[idx(name)]);return Number.isFinite(n)?n:fallback};
      const dietaryRaw=idx('dietary_type')>=0?(row[idx('dietary_type')]||''):'';
      const dietaryType:Editor['dietaryType']=dietaryRaw==='vegetarian'||dietaryRaw==='non_vegetarian'?dietaryRaw:'unspecified';
      const ok=await send('POST',{
        action:'create_item',categoryId,nameAr,
        nameEn:idx('name_en')>=0?(row[idx('name_en')]||''):'',
        nameFr:idx('name_fr')>=0?(row[idx('name_fr')]||''):'',
        descriptionAr:idx('description_ar')>=0?(row[idx('description_ar')]||''):'',
        descriptionEn:idx('description_en')>=0?(row[idx('description_en')]||''):'',
        descriptionFr:idx('description_fr')>=0?(row[idx('description_fr')]||''):'',
        price,
        discountPrice:idx('discount_price')>=0&&row[idx('discount_price')]!==''?num('discount_price'):null,
        taxRate:Math.max(0,Math.min(100,num('tax_rate',0))),
        taxIncluded:bool('tax_included',true),
        stockQuantity:Math.max(0,num('stock_quantity',0)),
        trackInventory:bool('track_inventory',false),
        dietaryType,
        sortOrder:data.items.filter(x=>x.category_id===categoryId).length+imported+1,
        imageUrl:'',imageUrls:[],
        calories:idx('calories')>=0&&row[idx('calories')]!==''?Math.max(0,num('calories')):null,
        enabled:bool('enabled',true),variants:[],addonGroups:[]
      });
      if(ok) imported++; else rejected++;setExcelProgress({done:rowIndex+1,total:importRows.length});
    }
    setMsg(L('تم استيراد '+imported+' صنف'+(rejected?'، ورفض '+rejected+' صف':''),'Imported '+imported+' items'+(rejected?', rejected '+rejected+' rows':''),'Importé '+imported+' articles'+(rejected?', '+rejected+' lignes rejetées':'')));
  }catch(e){setMsg(e instanceof Error?e.message:'EXCEL_IMPORT_FAILED')}
  finally{setBusy(false);setExcelProgress(null)}
}
 function importLibraryOption(groupIndex:number,option:ApiOption){patchGroup(groupIndex,{options:[...editor!.addonGroups[groupIndex].options,{name:local(option.name_ar,option.name_en,option.name_fr),priceDelta:String(option.price_delta),stockQuantity:String(option.stock_quantity||0),enabled:true}]})}
 const categoryName=(c:Pick<ApiCategory,'name_ar'|'name_en'|'name_fr'>)=>locale==='ar'?c.name_ar:locale==='fr'?c.name_fr||c.name_en||c.name_ar:c.name_en||c.name_ar;
 const visibleItems=data.items.filter(x=>(Boolean(categoryFilter)&&x.category_id===categoryFilter)&&(!itemSearch||`${x.name_ar} ${x.name_en} ${x.name_fr} ${x.description_ar||''} ${x.description_en||''}`.toLowerCase().includes(itemSearch.toLowerCase()))).sort((a,b)=>sortDirection==='asc'?Number(a.sort_order)-Number(b.sort_order):Number(b.sort_order)-Number(a.sort_order));
 const addonRows=data.items.flatMap(item=>item.addon_groups.flatMap((group,groupIndex)=>group.options.map((option,optionIndex)=>({item,group,option,groupIndex,optionIndex}))));
 const visibleAddonRows=addonRows.filter(({item,group,option})=>`${item.name_ar} ${item.name_en} ${group.title_ar} ${group.title_en} ${option.name_ar} ${option.name_en}`.toLowerCase().includes(addonSearch.toLowerCase()));
 const translations=(value:Localized,onChange:(value:Localized)=>void,kind:'name'|'description')=><div className="menu-locale-fields">{(['ar','en','fr'] as const).map((lang,i)=><label key={lang}>{lang==='ar'?'العربية':lang==='en'?'English':'Français'}<input dir={lang==='ar'?'rtl':'ltr'} required={kind==='name'&&lang==='ar'} maxLength={kind==='name'?180:4000} value={value[lang]} placeholder={kind==='description'?L('وصف اختياري','Optional description','Description facultative'):''} onChange={e=>onChange({...value,[lang]:e.target.value})}/></label>)}</div>;
 return <main className="restaurant-workspace-shell"><section className="restaurant-ops menu-reference-workspace">
  <div className="restaurant-ops-head"><div><span className="restaurant-ops-kicker"><BookOpen size={16}/>{L('إدارة المطعم','Restaurant management','Gestion du restaurant')}</span><h1>{L('المنيو والأصناف','Menu & items','Menu et articles')}</h1><p>{L('رتّب الأقسام، أدر الأصناف والإضافات، وراجع الأسعار والتوفر من مكان واحد.','Organize categories, items and add-ons, and manage pricing and availability in one place.','Organisez les catégories, articles et suppléments, et gérez les prix et disponibilités.')}</p><span className="menu-reference-editor-hint">{L('من تحرير الصنف يمكنك رفع الصور وضبط السعر الأساسي والأحجام والإضافات.','Open an item editor to upload images and manage base prices, sizes and add-ons.','Ouvrez un article pour téléverser des images et gérer le prix, les tailles et suppléments.')}</span></div><button className="primary-button" type="button" onClick={openNewItem}><Plus size={16}/>{L('إضافة صنف','Add item','Ajouter un article')}</button></div>
  <div className="menu-reference-tabs" role="tablist"><button type="button" role="tab" aria-selected={menuView==='items'} className={menuView==='items'?'active':''} onClick={()=>setMenuView('items')}><UtensilsCrossed size={17}/>{L('الأصناف','Items','Articles')}<b>{data.items.length}</b></button><button type="button" role="tab" aria-selected={menuView==='addons'} className={menuView==='addons'?'active':''} onClick={()=>setMenuView('addons')}><Tags size={17}/>{L('الإضافات','Add-ons','Suppléments')}<b>{addonRows.length}</b></button></div>
  {menuView==='items'?<>
   {hasNewDraft&&!editor&&<aside className="menu-draft-card"><div><strong>{L('لديك مسودة صنف محفوظة','You have a saved item draft','Vous avez un brouillon d’article enregistré')}</strong><p>{L('يمكنك استكمال بياناتها من حيث توقفت.','Continue where you left off.','Reprenez là où vous vous étiez arrêté.')}</p></div><button type="button" className="menu-reference-add" onClick={openNewItem}>{L('استكمال المسودة','Resume draft','Reprendre le brouillon')}</button></aside>}
   <div className="menu-reference-toolbar"><label className="menu-reference-search"><Search size={17}/><input value={itemSearch} onChange={e=>setItemSearch(e.target.value)} placeholder={L('ابحث عن صنف أو وصف','Search items or descriptions','Rechercher un article ou une description')}/></label><button type="button" className="menu-reference-tool" onClick={()=>setSortDirection(x=>x==='asc'?'desc':'asc')}>{L(sortDirection==='asc'?'ترتيب تصاعدي':'ترتيب تنازلي',sortDirection==='asc'?'Sort ascending':'Sort descending',sortDirection==='asc'?'Tri croissant':'Tri décroissant')}</button><button type="button" className="menu-reference-tool" onClick={()=>setShowCategories(x=>!x)}><Tags size={16}/>{L('إدارة الأقسام','Manage categories','Gérer les catégories')}</button><button type="button" className="menu-reference-add" onClick={openNewItem}><Plus size={16}/>{L('إضافة صنف','Add item','Ajouter un article')}</button></div>
   <div className="menu-category-gallery">{data.categories.filter(c=>Number(c.enabled)).map((c,index)=><button type="button" key={c.id} className={categoryFilter===c.id?'active':''} onClick={()=>setCategoryFilter(c.id)}><span className="menu-category-gallery-media">{c.image_url?<img src={c.image_url} alt=""/>:<UtensilsCrossed/>}</span><strong>{categoryName(c)}</strong><small>{data.items.filter(x=>x.category_id===c.id).length} {L('صنف','items','articles')}</small></button>)}</div>
   {showCategories&&<article className="menu-reference-category-panel"><div className="menu-reference-panel-head"><div><h2>{L('الأقسام','Categories','Catégories')}</h2><p>{L('أضف الأقسام ورتّب ظهور الأصناف فيها.','Add categories and organize menu items.','Ajoutez des catégories et organisez les articles.')}</p></div><button type="button" onClick={()=>setShowCategories(false)} aria-label={L('إغلاق','Close','Fermer')}>×</button></div><form className="menu-reference-category-form" onSubmit={saveCategory}>{translations(category,setCategory,'name')}<label className="menu-category-image-upload"><ImagePlus size={17}/>{categoryUploading?L('جارٍ رفع الصورة…','Uploading image…','Téléversement…'):L('صورة القسم · JPG / PNG / WebP','Category image · JPG / PNG / WebP','Image de catégorie · JPG / PNG / WebP')}<input type="file" accept="image/jpeg,image/png,image/webp" onChange={e=>{const f=e.target.files?.[0];if(f)void uploadCategoryImage(f);e.currentTarget.value=''}}/></label>{categoryImage&&<div className="menu-category-image-preview"><img src={categoryImage} alt=""/><button type="button" onClick={()=>setCategoryImage('')}>{L('إزالة الصورة','Remove image','Retirer l’image')}</button></div>}<button className="menu-reference-add" disabled={busy||categoryUploading}><Plus size={16}/>{categoryEditingId?L('حفظ تعديل القسم','Save category','Enregistrer'):L('إضافة القسم','Add category','Ajouter')}</button>{categoryEditingId&&<button type="button" className="menu-reference-tool" onClick={()=>{setCategoryEditingId('');setCategory(local());setCategoryImage('')}}>{L('إلغاء','Cancel','Annuler')}</button>}</form><div className="menu-reference-category-list">{data.categories.map((c,index)=><div key={c.id}><span className="menu-category-rank">{String(index+1).padStart(2,'0')}</span>{c.image_url?<img className="menu-category-thumb" src={c.image_url} alt=""/>:<span className="menu-category-thumb-fallback"><UtensilsCrossed size={15}/></span>}<strong>{categoryName(c)}</strong><span>{data.items.filter(x=>x.category_id===c.id).length} {L('أصناف','items','articles')}</span><button type="button" onClick={()=>{setCategoryEditingId(c.id);setCategory(local(c.name_ar,c.name_en,c.name_fr));setCategoryImage(c.image_url||'')}}>{L('تعديل','Edit','Modifier')}</button><button type="button" onClick={()=>void updateCategoryOrder(index,-1)} disabled={index===0} aria-label={L('رفع ترتيب القسم','Move category up','Monter la catégorie')}>↑</button><button type="button" onClick={()=>void updateCategoryOrder(index,1)} disabled={index===data.categories.length-1} aria-label={L('خفض ترتيب القسم','Move category down','Descendre la catégorie')}>↓</button><button type="button" onClick={()=>send('PATCH',{action:'toggle_category',id:c.id,enabled:!Number(c.enabled)})}>{Number(c.enabled)?L('إيقاف','Disable','Désactiver'):L('تفعيل','Enable','Activer')}</button><button type="button" onClick={()=>send('DELETE',{kind:'category',id:c.id})} disabled={data.items.some(x=>x.category_id===c.id)}>{L('حذف','Delete','Supprimer')}</button></div>)}</div></article>}
   {!categoryFilter&&<div className="menu-category-open-hint">{L('اختر فئة لعرض عناصرها','Choose a category to view its items','Choisissez une catégorie pour afficher ses articles')}</div>}{categoryFilter&&<><div className="menu-reference-results-head"><div><h2>{categoryFilter==='all'?L('كل الأصناف','All items','Tous les articles'):categoryName(data.categories.find(c=>c.id===categoryFilter)||data.categories[0]||{name_ar:'',name_en:'',name_fr:''})}</h2><p>{visibleItems.length} {L('صنف','items','articles')}</p></div><span>{L('لرفع الصورة وتحرير الأسعار والأحجام والإضافات اضغط «تعديل» على الصنف.','Choose Edit on an item to manage its image, prices, sizes and add-ons.','Choisissez Modifier pour gérer l’image, les prix, tailles et suppléments.')}</span></div>{(()=>{const selected=data.categories.find(c=>c.id===categoryFilter);return selected?<div className="menu-category-excel-zone"><strong>{categoryName(selected)}</strong><span>{L('استيراد أصناف هذا القسم من Excel','Import items into this category from Excel','Importer les articles de cette catégorie depuis Excel')}</span><div><button type="button" className="menu-reference-tool" onClick={()=>downloadCategoryExcelTemplate(selected)}><Download size={16}/>{L('تحميل قالب Excel','Download Excel template','Télécharger le modèle Excel')}</button><label className="menu-reference-add"><Upload size={16}/>{busy&&excelProgress?L('جارٍ الاستيراد '+excelProgress.done+'/'+excelProgress.total,'Importing '+excelProgress.done+'/'+excelProgress.total,'Importation '+excelProgress.done+'/'+excelProgress.total):L('رفع ملف Excel','Upload Excel','Importer Excel')}<input type="file" accept=".xls,application/vnd.ms-excel" hidden disabled={busy} onChange={e=>{const file=e.target.files?.[0];if(file)void importCategoryExcel(selected.id,file);e.currentTarget.value=''}}/></label>{busy&&excelProgress&&<div style={{width:'100%',marginTop:8}}><progress value={excelProgress.done} max={Math.max(1,excelProgress.total)} style={{width:'100%'}}/><small>{Math.round((excelProgress.done/Math.max(1,excelProgress.total))*100)}%</small></div>}</div></div>:null})()}
   <div className="menu-reference-item-grid">{visibleItems.length===0?<div className="menu-reference-empty"><UtensilsCrossed/><strong>{L('لا توجد أصناف هنا بعد','No items here yet','Aucun article ici pour le moment')}</strong><span>{L('أضف صنفًا أو غيّر القسم المحدد.','Add an item or choose a different category.','Ajoutez un article ou choisissez une autre catégorie.')}</span><button type="button" className="menu-reference-add" onClick={()=>setEditor(emptyEditor(data.categories[0]?.id||'',data.items.length+1))}><Plus size={16}/>{L('إضافة صنف','Add item','Ajouter un article')}</button></div>:visibleItems.map(item=><article className="menu-reference-item-card" key={item.id}><div className="menu-reference-item-media"><b className="menu-reference-item-number">{String(data.items.findIndex(x=>x.id===item.id)+1).padStart(2,'0')}</b>{item.image_url?<img src={item.image_url} alt={item.name_ar} loading="lazy"/>:<span><UtensilsCrossed/></span>}<button type="button" className="menu-reference-edit-overlay" onClick={()=>startEdit(item)}>{L('تعديل','Edit','Modifier')}</button><button type="button" className={Number(item.enabled)?'is-available':'is-paused'} onClick={()=>send('PATCH',{action:'toggle_item',id:item.id,enabled:!Number(item.enabled)})}>{Number(item.enabled)?L('متاح','Available','Disponible'):L('متوقف','Unavailable','Indisponible')}</button></div><div className="menu-reference-item-copy"><small>{categoryName(data.categories.find(c=>c.id===item.category_id)||{name_ar:'',name_en:'',name_fr:''})}</small><h3>{locale==='ar'?item.name_ar:locale==='fr'?item.name_fr||item.name_en||item.name_ar:item.name_en||item.name_ar}</h3>{(locale==='ar'?item.description_ar:locale==='fr'?item.description_fr||item.description_en:item.description_en||item.description_ar)&&<p>{locale==='ar'?item.description_ar:locale==='fr'?item.description_fr||item.description_en:item.description_en||item.description_ar}</p>}<div className="menu-reference-item-meta"><span>{Number(item.track_inventory)?`${L('المخزون','Stock','Stock')}: ${item.stock_quantity}`:L('مخزون غير متتبع','Stock untracked','Stock non suivi')}</span><span>{item.dietary_type==='vegetarian'?L('نباتي','Vegetarian','Végétarien'):item.dietary_type==='non_vegetarian'?L('غير نباتي','Non-vegetarian','Non végétarien'):L('غير محدد','Unspecified','Non précisé')}</span><span>{item.tax_rate}% · {Number(item.tax_included)?L('شامل','incl. tax','TTC'):L('غير شامل','excl. tax','HT')}</span><span>{item.variants.length} {L('حجم','sizes','tailles')}</span><span>{item.addon_groups.reduce((n,g)=>n+g.options.length,0)} {L('إضافة','add-ons','suppléments')}</span></div><footer><strong>{item.discount_price!=null&&<del className="menu-price-old">{Number(item.price).toFixed(2)}</del>}<span className="menu-price-current">{Number(item.discount_price??item.price).toFixed(2)}</span> <small>{item.discount_price!=null?L('بعد الخصم','after discount','prix remisé'):L('السعر الأساسي','base price','prix de base')}</small></strong><div><button type="button" onClick={()=>void updateItemOrder(item,-1)} aria-label={L('رفع ترتيب الصنف','Move item up','Monter l’article')}>↑</button><button type="button" onClick={()=>void updateItemOrder(item,1)} aria-label={L('خفض ترتيب الصنف','Move item down','Descendre l’article')}>↓</button><button type="button" className="menu-reference-edit-item" onClick={()=>startEdit(item)}>{L('تحرير الصنف','Edit item','Modifier l’article')}</button><button type="button" className="danger" onClick={()=>{if(window.confirm(L(`حذف ${item.name_ar}؟`,`Delete ${item.name_en||item.name_ar}?`,`Supprimer ${item.name_fr||item.name_ar} ?`)))void send('DELETE',{kind:'item',id:item.id})}}>{L('حذف','Delete','Supprimer')}</button></div></footer></div></article>)}</div></>}
  </>:<>
   <div className="menu-reference-toolbar"><label className="menu-reference-search"><Search size={17}/><input value={addonSearch} onChange={e=>setAddonSearch(e.target.value)} placeholder={L('ابحث بالصنف أو المجموعة أو الإضافة','Search item, group or add-on','Rechercher article, groupe ou supplément')}/></label><button type="button" className="menu-reference-tool" onClick={exportAddons}><Download size={16}/>{L('تصدير المكتبة CSV','Export library CSV','Exporter CSV')}</button><input ref={addonCsvRef} type="file" accept=".csv,text/csv" hidden onChange={e=>{const f=e.target.files?.[0];if(f)void importAddons(f);e.currentTarget.value=''}}/><button type="button" className="menu-reference-tool" onClick={()=>addonCsvRef.current?.click()}><Upload size={16}/>{L('استيراد CSV','Import CSV','Importer CSV')}</button></div>
   <article className="menu-reference-table-card"><div className="menu-reference-panel-head"><div><h2>{L('إضافات الأصناف','Item add-ons','Suppléments des articles')}</h2><p>{L('كل خيار مرتبط بصنف ومجموعة اختيار، مع سعره ومخزونه وحالته.','Each option belongs to an item and selection group, with its own price, stock and status.','Chaque choix est lié à un article et un groupe, avec son prix, stock et statut.')}</p></div><span className="menu-reference-count">{visibleAddonRows.length}</span></div><div className="menu-reference-table-wrap"><table><thead><tr><th>#</th><th>{L('المجموعة','Group','Groupe')}</th><th>{L('الإضافة','Add-on','Supplément')}</th><th>{L('الصنف','Item','Article')}</th><th>{L('السعر','Price','Prix')}</th><th>{L('المخزون','Stock','Stock')}</th><th>{L('الحالة','Status','Statut')}</th><th>{L('إجراء','Action','Action')}</th></tr></thead><tbody>{visibleAddonRows.length===0?<tr><td colSpan={8}><div className="menu-reference-empty compact"><Tags/><strong>{L('لا توجد إضافات مطابقة','No matching add-ons','Aucun supplément correspondant')}</strong><span>{L('أضف المجموعات والخيارات من تحرير الصنف أو احفظ خيارات شائعة في المكتبة.','Add groups and options while editing an item, or save common choices to the library.','Ajoutez des groupes et choix dans un article ou enregistrez-les dans la bibliothèque.')}</span></div></td></tr>:visibleAddonRows.map(({item,group,option},index)=><tr key={option.id}><td>{index+1}</td><td><span className="menu-reference-group-chip">{locale==='ar'?group.title_ar:locale==='fr'?group.title_fr||group.title_en||group.title_ar:group.title_en||group.title_ar}</span></td><td><strong>{locale==='ar'?option.name_ar:locale==='fr'?option.name_fr||option.name_en||option.name_ar:option.name_en||option.name_ar}</strong></td><td>{locale==='ar'?item.name_ar:locale==='fr'?item.name_fr||item.name_en||item.name_ar:item.name_en||item.name_ar}</td><td>+{Number(option.price_delta).toFixed(2)}</td><td>{Number(option.stock_quantity||0)===0?L('غير محدود','untracked','illimité'):option.stock_quantity}</td><td><span className={Number(option.enabled)?'menu-reference-status on':'menu-reference-status off'}>{Number(option.enabled)?L('متاح','Available','Disponible'):L('متوقف','Paused','Désactivé')}</span></td><td><button type="button" className="menu-reference-row-action" onClick={()=>startEdit(item)}>{L('فتح الصنف','Open item','Ouvrir')}</button></td></tr>)}</tbody></table></div></article>
   <article className="menu-reference-library-card"><div className="menu-reference-panel-head"><div><h2>{L('مكتبة الإضافات القابلة لإعادة الاستخدام','Reusable add-on library','Bibliothèque réutilisable')}</h2><p>{L('أضف الخيارات الشائعة بسرعة إلى أي مجموعة داخل الصنف.','Quickly add common choices to any item group.','Ajoutez rapidement des choix fréquents à un groupe.')}</p></div></div><form className="menu-reference-library-form" onSubmit={async e=>{e.preventDefault();const saved=editingLibrary?await send('PATCH',{id:editingLibrary,nameAr:libraryForm.name.ar,nameEn:libraryForm.name.en,nameFr:libraryForm.name.fr,priceDelta:Number(libraryForm.price),stockQuantity:Number(libraryForm.stockQuantity||0),enabled:libraryForm.enabled},'/api/restaurant/menu/library'):await send('POST',{action:'create_addon_library',nameAr:libraryForm.name.ar,nameEn:libraryForm.name.en,nameFr:libraryForm.name.fr,priceDelta:Number(libraryForm.price),stockQuantity:Number(libraryForm.stockQuantity||0),enabled:true});if(saved){setLibraryForm({name:local(),price:'0',stockQuantity:'0',enabled:true});setEditingLibrary('')}}}>{translations(libraryForm.name,name=>setLibraryForm(x=>({...x,name})),'name')}<label>{L('السعر الإضافي','Extra price','Supplément')}<input type="number" min="0" step="0.01" value={libraryForm.price} onChange={e=>setLibraryForm(x=>({...x,price:e.target.value}))}/></label><label>{L('المخزون (0 غير محدود)','Stock (0 unlimited)','Stock (0 illimité)')}<input type="number" min="0" step="1" value={libraryForm.stockQuantity} onChange={e=>setLibraryForm(x=>({...x,stockQuantity:e.target.value}))}/></label>{editingLibrary&&<label className="menu-check-label"><input type="checkbox" checked={libraryForm.enabled} onChange={e=>setLibraryForm(x=>({...x,enabled:e.target.checked}))}/>{L('متاحة','Available','Disponible')}</label>}<button type="submit" className="menu-reference-add" disabled={busy}><Plus size={16}/>{editingLibrary?L('حفظ التعديل','Save changes','Enregistrer les changements'):L('إضافة للمكتبة','Add to library','Ajouter à la bibliothèque')}</button>{editingLibrary&&<button type="button" className="menu-reference-tool" onClick={()=>{setEditingLibrary('');setLibraryForm({name:local(),price:'0',stockQuantity:'0',enabled:true})}}>{L('إلغاء','Cancel','Annuler')}</button>}</form><div className="menu-reference-library-list">{data.addonLibrary.filter((x:ApiOption)=>`${x.name_ar} ${x.name_en} ${x.name_fr}`.toLowerCase().includes(addonSearch.toLowerCase())).map((x:ApiOption)=><div key={x.id}><span><strong>{locale==='ar'?x.name_ar:locale==='fr'?x.name_fr||x.name_en||x.name_ar:x.name_en||x.name_ar}</strong><small>+{Number(x.price_delta).toFixed(2)} · {Number(x.stock_quantity||0)===0?L('مخزون غير محدود','unlimited stock','stock illimité'):Number(x.stock_quantity)}</small></span><button type="button" onClick={()=>{setEditingLibrary(x.id);setLibraryForm({name:local(x.name_ar,x.name_en,x.name_fr),price:String(x.price_delta),stockQuantity:String(x.stock_quantity||0),enabled:Boolean(Number(x.enabled))})}}>{L('تعديل','Edit','Modifier')}</button><button type="button" onClick={()=>send('POST',{action:'create_addon_library',nameAr:x.name_ar+' - نسخة',nameEn:x.name_en+' copy',nameFr:x.name_fr+' copie',priceDelta:Number(x.price_delta),stockQuantity:Number(x.stock_quantity||0),enabled:true})}><Copy size={15}/></button><button type="button" onClick={()=>send('PATCH',{action:'toggle_addon_library',id:x.id,enabled:!Number(x.enabled)})}>{Number(x.enabled)?L('إيقاف','Disable','Désactiver'):L('تفعيل','Enable','Activer')}</button><button type="button" onClick={()=>send('DELETE',{kind:'addon_library',id:x.id})}>{L('حذف','Delete','Supprimer')}</button></div>)}</div></article>
  </>}
 {editor&&<div className="menu-editor-backdrop" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget)closeEditor()}}><form className="menu-editor-panel menu-editor-panel-v2" onSubmit={saveItem} aria-label={L('تحرير الصنف','Edit item','Modifier l’article')}><header className="menu-editor-header-v2"><div><h2>{editor.id?L('تعديل الصنف','Edit item','Modifier l’article'):L('صنف جديد','New item','Nouvel article')}</h2><p>{L('أكمل بيانات الصنف وصورته وأسعاره وخياراته.','Set item details, image, sizes and add-ons.','Renseignez l’article, son image, ses tailles et suppléments.')}</p><nav className="menu-editor-steps" aria-label={L('مراحل إضافة الصنف','Item editor steps','Étapes de l’article')}><button type="button" className={editorStep===1?'active':''} onClick={()=>setEditorStep(1)}><b>1</b><span>{L('البيانات','Details','Détails')}</span></button><button type="button" className={editorStep===2?'active':''} onClick={()=>setEditorStep(2)}><b>2</b><span>{L('الصورة والسعر','Image & price','Image et prix')}</span></button><button type="button" className={editorStep===3?'active':''} onClick={()=>setEditorStep(3)}><b>3</b><span>{L('الأحجام والإضافات','Options','Options')}</span></button></nav></div><button type="button" onClick={closeEditor} aria-label={L('إغلاق','Close','Fermer')}>×</button></header><div className="menu-editor-content menu-editor-content-v2">
 <section className={"menu-editor-section menu-editor-step-section "+(editorStep===1?"is-active":"")}><h3>{L('بيانات الصنف','Item details','Détails')}</h3><label>{L('القسم','Category','Catégorie')}<select required value={editor.categoryId} onChange={e=>patchEditor({categoryId:e.target.value})}>{data.categories.map((c:ApiCategory)=><option key={c.id} value={c.id}>{c.name_ar}</option>)}</select></label><label>{L('السعر الأساسي','Base price','Prix de base')}<input required type="number" min="0" max="999999999" step="0.01" value={editor.price} onChange={e=>patchEditor({price:e.target.value})}/></label><label>{L('سعر الخصم (اختياري)','Discount price (optional)','Prix remisé (facultatif)')}<input type="number" min="0" max={editor.price||'999999999'} step="0.01" value={editor.discountPrice} onChange={e=>patchEditor({discountPrice:e.target.value})}/></label><label>{L('ضريبة الصنف (%)','Item tax rate (%)','Taux de taxe (%)')}<input type="number" min="0" max="100" step="0.01" value={editor.taxRate} onChange={e=>patchEditor({taxRate:e.target.value})}/></label><label className="menu-check-label"><input type="checkbox" checked={editor.taxIncluded} onChange={e=>patchEditor({taxIncluded:e.target.checked})}/>{L('السعر شامل الضريبة','Price includes tax','Prix TTC')}</label><label className="menu-check-label"><input type="checkbox" checked={editor.trackInventory} onChange={e=>patchEditor({trackInventory:e.target.checked})}/>{L('تتبع مخزون الصنف','Track item stock','Suivre le stock')}</label>{editor.trackInventory&&<label>{L('كمية المخزون','Stock quantity','Quantité en stock')}<input type="number" min="0" max="10000000" value={editor.stockQuantity} onChange={e=>patchEditor({stockQuantity:e.target.value})}/></label>}<label>{L('نوع الصنف الغذائي','Dietary type','Type alimentaire')}<select value={editor.dietaryType} onChange={e=>patchEditor({dietaryType:e.target.value as Editor['dietaryType']})}><option value="unspecified">{L('غير محدد','Unspecified','Non précisé')}</option><option value="vegetarian">{L('نباتي','Vegetarian','Végétarien')}</option><option value="non_vegetarian">{L('غير نباتي','Non-vegetarian','Non végétarien')}</option></select></label><label>{L('ترتيب الصنف','Item order','Ordre de l’article')}<input type="number" min="0" value={editor.sortOrder} onChange={e=>patchEditor({sortOrder:e.target.value})}/></label><label>{L('السعرات الحرارية (اختياري)','Calories (optional)','Calories (facultatif)')}<input type="number" min="0" step="1" value={editor.calories} onChange={e=>patchEditor({calories:e.target.value})}/></label><h4>{L('اسم الصنف باللغات','Names in each language','Noms dans chaque langue')}</h4>{translations(editor.name,v=>patchEditor({name:v}),'name')}<h4>{L('الوصف باللغات','Descriptions in each language','Descriptions dans chaque langue')}</h4>{translations(editor.description,v=>patchEditor({description:v}),'description')}</section>
 <section className={"menu-editor-section menu-editor-step-section "+(editorStep===2?"is-active":"")}><h3>{L('صورة الصنف','Item image','Image de l’article')}</h3><label className="menu-image-upload"><ImagePlus/><span>{uploading?L('جارٍ رفع الصورة…','Uploading image…','Téléversement…'):L('رفع JPG أو PNG أو WebP (حتى 5MB)','Upload JPG, PNG or WebP (up to 5MB)','Téléverser JPG, PNG ou WebP (5 Mo max.)')}<input type="file" multiple accept="image/jpeg,image/png,image/webp" onChange={e=>{const files=Array.from(e.target.files||[]).slice(0,8);for(const f of files)void upload(f);e.currentTarget.value=''}}/></span></label>{editor.imageUrls.length>0&&<div className="menu-image-gallery-editor">{editor.imageUrls.map((url,index)=><div className="menu-image-preview" key={url}><img src={url} alt={editor.name.ar}/><button type="button" onClick={()=>patchEditor({imageUrls:editor.imageUrls.filter(x=>x!==url),imageUrl:editor.imageUrl===url?(editor.imageUrls.find(x=>x!==url)||''):editor.imageUrl})}>{L('إزالة','Remove','Retirer')}</button>{index===0&&<b>{L('الرئيسية','Primary','Principale')}</b>}</div>)}</div>}</section>
 <section className={"menu-editor-section menu-editor-step-section "+(editorStep===3?"is-active":"")}><div className="menu-section-heading"><div><h3>{L('الأحجام والأسعار','Sizes and prices','Tailles et tarifs')}</h3><p>{L('أضف حجمًا وسعره الإضافي مقارنة بالسعر الأساسي.','Add sizes and their price difference from the base price.','Ajoutez des tailles et leur supplément au prix de base.')}</p></div><button type="button" onClick={()=>patchEditor({variants:[...editor.variants,{name:local(),priceDelta:'0',enabled:true}]})}><Plus size={16}/>{L('إضافة حجم','Add size','Ajouter une taille')}</button></div>{editor.variants.map((v,i)=><div className="menu-option-editor" key={i}><div>{translations(v.name,name=>patchVariant(i,{name}),'name')}</div><label>{L('فرق السعر','Price difference','Supplément')}<input type="number" step="0.01" value={v.priceDelta} onChange={e=>patchVariant(i,{priceDelta:e.target.value})}/></label><label className="menu-check-label"><input type="checkbox" checked={v.enabled} onChange={e=>patchVariant(i,{enabled:e.target.checked})}/>{L('متاح','Available','Disponible')}</label><button type="button" onClick={()=>patchEditor({variants:editor.variants.filter((_,n)=>n!==i)})} aria-label={L('حذف الحجم','Remove size','Supprimer la taille')}><Trash2/></button></div>)}</section>
 <section className={"menu-editor-section menu-editor-step-section "+(editorStep===3?"is-active":"")}><div className="menu-section-heading"><div><h3>{L('مجموعات الإضافات','Add-on groups','Groupes de suppléments')}</h3><p>{L('مثال: الجبن، الصلصات، درجة الطهي. لكل اختيار سعر وقواعد مستقلة.','Examples: cheese, sauces, doneness. Each option has its own price and rules.','Exemples : fromage, sauces, cuisson. Chaque choix a son prix et ses règles.')}</p></div><button type="button" onClick={()=>patchEditor({addonGroups:[...editor.addonGroups,emptyGroup()]})}><Plus size={16}/>{L('إضافة مجموعة','Add group','Ajouter un groupe')}</button></div>{editor.addonGroups.map((g,gi)=><article className="menu-addon-editor" key={gi}><div className="menu-section-heading"><h4>{L('مجموعة إضافات','Add-on group','Groupe de suppléments')} {gi+1}</h4><label className="menu-check-label"><input type="checkbox" checked={g.enabled} onChange={e=>patchGroup(gi,{enabled:e.target.checked})}/>{L('مفعّلة','Active','Active')}</label><button type="button" onClick={()=>patchEditor({addonGroups:editor.addonGroups.filter((_,n)=>n!==gi)})} aria-label={L('حذف المجموعة','Remove group','Supprimer le groupe')}><Trash2/></button></div>{translations(g.title,title=>patchGroup(gi,{title}),'name')}<div className="menu-addon-rules"><label>{L('نوع الاختيار','Selection type','Type de choix')}<select value={g.selectionType} onChange={e=>patchGroup(gi,{selectionType:e.target.value as Group['selectionType'],maxQty:e.target.value==='single'?'1':g.maxQty,maxSelect:e.target.value==='single'?'1':g.maxSelect})}><option value="single">{L('اختيار واحد','Single choice','Choix unique')}</option><option value="multiple">{L('اختيارات متعددة','Multiple choices','Choix multiples')}</option></select></label><label className="menu-check-label"><input type="checkbox" checked={g.isRequired} onChange={e=>patchGroup(gi,{isRequired:e.target.checked,minSelect:e.target.checked&&Number(g.minSelect)<1?'1':g.minSelect})}/>{L('إلزامية','Required','Obligatoire')}</label><label>{L('الحد الأدنى','Minimum picks','Minimum')}<input type="number" min="0" max="30" value={g.minSelect} onChange={e=>patchGroup(gi,{minSelect:e.target.value})}/></label><label>{L('الحد الأعلى (0 بلا حد)','Maximum (0 = no limit)','Maximum (0 = sans limite)')}<input type="number" min="0" max="30" value={g.maxSelect} onChange={e=>patchGroup(gi,{maxSelect:e.target.value})}/></label><label>{L('أقصى كمية لكل خيار','Max quantity per option','Quantité max. par choix')}<input type="number" min="1" max="99" value={g.maxQty} onChange={e=>patchGroup(gi,{maxQty:e.target.value})}/></label></div><div className="menu-section-heading"><h5>{L('الخيارات وأسعارها','Options and prices','Choix et tarifs')}</h5><span>{data.addonLibrary.filter(x=>Number(x.enabled)).map(x=><button className="menu-library-chip" type="button" key={x.id} onClick={()=>importLibraryOption(gi,x)}>{x.name_ar} +{Number(x.price_delta).toFixed(2)}</button>)}</span></div>{g.options.map((o,oi)=><div className="menu-option-editor" key={oi}><div>{translations(o.name,name=>patchOption(gi,oi,{name}),'name')}</div><label>{L('السعر الإضافي','Extra price','Supplément')}<input type="number" min="0" step="0.01" value={o.priceDelta} onChange={e=>patchOption(gi,oi,{priceDelta:e.target.value})}/></label><label>{L('المخزون (0 غير محدود)','Stock (0 unlimited)','Stock (0 illimité)')}<input type="number" min="0" step="1" value={o.stockQuantity} onChange={e=>patchOption(gi,oi,{stockQuantity:e.target.value})}/></label><label className="menu-check-label"><input type="checkbox" checked={o.enabled} onChange={e=>patchOption(gi,oi,{enabled:e.target.checked})}/>{L('متاح','Available','Disponible')}</label><button type="button" onClick={()=>patchGroup(gi,{options:g.options.filter((_,n)=>n!==oi)})} aria-label={L('حذف الخيار','Remove option','Supprimer le choix')}><Trash2/></button></div>)}<button type="button" className="menu-add-option" onClick={()=>patchGroup(gi,{options:[...g.options,emptyOption()]})}><Plus size={15}/>{L('إضافة خيار','Add option','Ajouter un choix')}</button></article>)}</section></div><footer className="menu-editor-footer-v2"><p role="status">{msg}</p><div className="menu-editor-step-actions">{editorStep>1&&<button className="quiet-button" type="button" onClick={()=>setEditorStep((editorStep-1) as 1|2|3)}>{L("السابق","Back","Précédent")}</button>}{editorStep<3&&<button className="primary-button" type="button" onClick={()=>setEditorStep((editorStep+1) as 1|2|3)}>{L("التالي","Next","Suivant")}</button>}</div><button className="primary-button menu-editor-save-v2" type="submit" disabled={busy||uploading||!editor.categoryId}><Save size={16}/>{busy?L('جارٍ الحفظ…','Saving…','Enregistrement…'):editor.id?L('حفظ التعديلات','Save changes','Enregistrer les modifications'):L('حفظ الصنف وإضافته للمنيو','Save item to menu','Enregistrer l’article dans le menu')}</button><button className="quiet-button menu-editor-draft-v2" type="button" onClick={saveDraftAndClose}><Save size={15}/>{L('حفظ كمسودة','Save draft','Enregistrer le brouillon')}</button></footer></form></div>}
 <p role="status">{msg}</p></section></main>;
}
